SLOT_KEYS = {"Morning (8 AM)": "slot_m", "Afternoon (2 PM)": "slot_a", "Night (9 PM)": "slot_n"}


def lang():
    return st.session_state.get("lang", "en")


def t(key, **kwargs):
    entry = TEXT.get(key)
    if entry is None:
        return key
    text = entry.get(lang()) or entry["en"]
    return text.format(**kwargs) if kwargs else text


def slot(name):
    """Translate an internal slot name like 'Morning (8 AM)'."""
    return t(SLOT_KEYS[name]) if name in SLOT_KEYS else name


def big_text_css():
    if st.session_state.get("big_text", True):
        st.markdown(
            "<style>.stApp p, .stApp li, .stApp label, .stApp button, .stApp input, "
            ".stApp textarea {font-size: 1.25rem !important;} "
            ".stApp h1 {font-size: 2.6rem !important;}</style>",
            unsafe_allow_html=True,
        )
